SelectionModes.Mode:
SELECT
MMS_Teachers.TeacherCode {COL MMS_Teachers.TeacherCode},
MMS_Teachers.TeacherName {COL MMS_Teachers.TeacherName},
MMS_Teachers.Disabled {COL MMS_Teachers.Disabled}
FROM
MMS_Teachers
WHERE
(
MMS_Teachers.TeacherCode LIKE {IN FILTER_VALUE} OR
MMS_Teachers.TeacherName LIKE {IN FILTER_VALUE}
)

{WHEN Disabled == 0 EXPAND {AND MMS_Teachers.Disabled = {FALSE}}}
{WHEN Disabled == 1 EXPAND {AND MMS_Teachers.Disabled = {TRUE}}}

SELECT
MMS_Teachers.TeacherCode {COL MMS_Teachers.TeacherCode},
MMS_Teachers.TeacherName {COL MMS_Teachers.TeacherName},
MMS_Teachers.Disabled {COL MMS_Teachers.Disabled}
FROM
MMS_Teachers
WHERE
(
MMS_Teachers.TeacherCode = {IN FILTER_VALUE}
)
